// Configure Validin API authentication for user or global scope
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)

    if ($cmdopts.self) {
        $lib.print("Setting Validin API key for the current user.")
    } else {
        $lib.print("Setting Validin API key for all users.")
    }

    $key_status_ok = $privsep.setValidinAPIKey($cmdopts.apikey, $cmdopts.self)

    if ($key_status_ok) {
        $privsep.debugPrint("Setup", "Validin API key set successfully")
    } else {
        $lib.warn("Failed setting the key for the Validin API. Check if the token you provided is valid.")
    }

}

// Configure the tag prefix used for Validin enrichment tags
init {
    $privsep = $lib.import(ex.validin.privsep)

    $privsep.setTagPrefix($cmdopts.tagname)
    $lib.print("Changed the Validin tag prefix to #{p}", p=$privsep.getTagPrefix())
}

// Configure the Validin API hostname
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)

    $lib.print("Setting Validin API hostname for all users.")


    $hostname_status_ok = $privsep.setValidinAPIHostname($cmdopts.hostname)
    if ($hostname_status_ok) {
        $privsep.debugPrint("Setup", `Validin API hostname set successfully: {$cmdopts.hostname}`)
    } 

}

// Retrieve passive DNS records for IPs and domains, with optional extra records
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $api = $lib.import(ex.validin.api, debug=$lib.debug)
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)
}

$api_key_set = $privsep.getValidinAPIKey()

if ($api_key_set != $lib.false) {

    switch $node.form() {
        "inet:ipv4": { 
            $data = $api.getIpPDNS($node.repr()) 
            if ($data) {
                divert $cmdopts.yield $privsep.parseIpPDNS($data)
            }
        }
        "inet:fqdn": {
            tee 
            {
                $data = $api.getDomainPDNS($node.repr())
                if ($data) {
                    divert $cmdopts.yield $privsep.parseDomainPDNS($data)
                }
            }
            // If the user requested extra DNS records, fetch them
            // and yield them as well.
            {            
                if ($cmdopts.include_extra) {
                    $extra_dns = $api.getExtraDomainPDNS($node.repr())
                    if ($extra_dns) {
                        divert $cmdopts.yield $privsep.parseDomainPDNS($extra_dns)
                    }
                }
            }
        }
        *: { $privsep.debugPrint("PDNS", `unsupported form received: {$node.form()}`) }
    }

} else {
    $lib.exit("Validin API key not set and is needed to use this function, please run 'ex.validin.setup.apikey' first")
}

// Enumerate subdomains for a given FQDN using Validin's subdomain database
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $api = $lib.import(ex.validin.api, debug=$lib.debug)
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)
}

$api_key_set = $privsep.getValidinAPIKey()

if ($api_key_set != $lib.false) {

    switch $node.form() {
        "inet:fqdn": {
            $data = $api.getDomainSubdomains($node.repr())
            if ($data) {
                divert $cmdopts.yield $privsep.parseDomains($data)
            }

        }
        *: { $privsep.debugPrint("Subdomains", `unsupported form received: {$node.form()}`) }
    }

} else {
    $lib.exit("Validin API key not set and is needed to use this function, please run 'ex.validin.setup.apikey' first")
}

// Retrieve host crawl data creating HTTP requests, flows, and SSL certificates
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $api = $lib.import(ex.validin.api, debug=$lib.debug)
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)
}

$api_key_set = $privsep.getValidinAPIKey()

if ($api_key_set != $lib.false) {

    switch $node.form() {
        "inet:ipv4": { 
            $data = $api.getIpCrawlHistory($node.repr()) 
            if ($data) {
                divert $cmdopts.yield $privsep.parseCrawlResponse($data)
            }
        }
        "inet:fqdn": {
            $data = $api.getDomainCrawlHistory($node.repr())
            if ($data) {
                divert $cmdopts.yield $privsep.parseCrawlResponse($data)
            }

        }
        *: { $privsep.debugPrint("Host Responses", `unsupported form received: {$node.form()}`) }
    }

} else {
    $lib.exit("Validin API key not set and is needed to use this function, please run 'ex.validin.setup.apikey' first")
}

// Execute advanced search queries against Validin's crawl database
// Creates it:exec:query nodes and yields matching host data
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $api = $lib.import(ex.validin.api, debug=$lib.debug)
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)
}

$api_key_set = $privsep.getValidinAPIKey()

if ($api_key_set != $lib.false) {

    $search_results = $api.getAdvancedSearchResults($cmdopts.query)
    if ($search_results) {
        yield $privsep.parseCrawlResponse($search_results, create_query=$lib.true, query=$cmdopts.query)
    }


} else {
    $lib.exit("Validin API key not set and is needed to use this function, please run 'ex.validin.setup.apikey' first")
}

// Retrieve domain registration history from Validin
// Creates inet:whois:rec nodes with temporal data
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $api = $lib.import(ex.validin.api, debug=$lib.debug)
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)
}

$api_key_set = $privsep.getValidinAPIKey()

if ($api_key_set != $lib.false) {
    // Pivot to zone (apex domain) for WHOIS lookup
    :zone -> inet:fqdn {
        $zone_domain = $node.repr()
        $privsep.debugPrint("WHOIS", `Getting registration history for zone: {$zone_domain}`)

        $data = $api.getDomainRegHistory($zone_domain)

        if ($data) {
            divert $cmdopts.yield $privsep.emitDomainRegHistory($data)
        }
    }
} else {
    $lib.exit("Validin API key not set and is needed to use this function, please run 'ex.validin.setup.apikey' first")
}

// Retrieve all accessible Validin projects and create proj:project nodes
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $api = $lib.import(ex.validin.api, debug=$lib.debug)
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)
}

$api_key_set = $privsep.getValidinAPIKey()

if ($api_key_set != $lib.false) {

    $project_data = $api.getProjectList()
    if ($project_data) {
        divert $cmdopts.yield $privsep.parseProjectList($project_data)
    } else {
        $lib.warn("Failed to retrieve project list from Validin API")
    }

} else {
    $lib.exit("Validin API key not set and is needed to use this function, please run 'ex.validin.setup.apikey' first")
}

// Retrieve project indicators and create (refs) edges to proj:project nodes
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $api = $lib.import(ex.validin.api, debug=$lib.debug)
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)
}

$api_key_set = $privsep.getValidinAPIKey()

if ($api_key_set != $lib.false) {
    $project_guid = $node.repr()
    $validin_guid = $node.props.get("_validin:guid")

    $privsep.debugPrint("Get", `Starting get indicators for {$validin_guid}`)

    $indicator_data = $api.getProjectIndicators($validin_guid)
    if ($indicator_data) {
        if ($cmdopts.yield) {
            yield $privsep.parseProjectIndicators($indicator_data, $project_guid)
        } else {
            $privsep.parseProjectIndicators($indicator_data, $project_guid)
        }
        $privsep.debugPrint("Get", `Successfully retrieved indicators`)
    } else {
        $lib.warn(`Failed to retrieve indicators for project: {$validin_guid}`)
    }

} else {
    $lib.exit("Validin API key not set and is needed to use this function, please run 'ex.validin.setup.apikey' first")
}

// Add indicators to a Validin project by form type
// Supports domains, IPs, and hashes with proper categorization
init {
    if $cmdopts.debug { $lib.debug = $lib.true }
    $api = $lib.import(ex.validin.api, debug=$lib.debug)
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)
}

$api_key_set = $privsep.getValidinAPIKey()

if ($api_key_set != $lib.false) {

    // Resolve project identifier (name or GUID) to get both project GUID and Validin GUID
    ($success, $project_guid, $validin_guid) = $privsep.resolveProjectIdentifier($cmdopts.project_identifier)

    if (not $success) {
        $lib.warn(`Project not found: {$cmdopts.project_identifier}. Run 'ex.validin.project.list' to sync projects first.`)
        return()
    }

    // Initialize payload structure
    $payload = ({
        "types": ({
            "dom": ([]),
            "ip": ([]),
            "hash": ([]),
            "raw": ([])
        })
    })

    $indicator_value = $node.repr()

    switch $node.form() {
        "inet:fqdn": {
            $payload.types.dom.append($indicator_value)
        }
        ("inet:ipv4", "inet:ipv6"): {
            $payload.types.ip.append($indicator_value)
        }
        ("hash:md5", "hash:sha1", "hash:sha256"): {
            $payload.types.hash.append($indicator_value)
        }
        *: {
            $lib.warn("Unsupported form for indicator addition: {f}", f=$node.form())
            return()
        }
    }

    $privsep.debugPrint("Add", `Starting add {$node.form()}={$indicator_value}`)

    $result = $api.addProjectIndicators($validin_guid, $payload)
    if ($result) {
        [ <(refs)+ { proj:project=$project_guid } ]
        $privsep.debugPrint("Add", `Successfully added {$node.form()}={$indicator_value}`)
    } else {
        $lib.warn(`Failed to add indicator to project`)
    }

} else {
    $lib.exit("Validin API key not set and is needed to use this function, please run 'ex.validin.setup.apikey' first")
}

// Remove indicators from a Validin project and clean up (refs) edges
init {
